{
  "name": "SUN RPC UDP客户端组件",
  "name_en": "SUN RPC UDP Client Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于通过 UDP 实现 SUN RPC 客户端/服务端通信，借助端口映射器发现服务端口，并完成 XDR 数据的打包、解包与远程过程调用。它适用于实验系统中需要访问基于 RPC 的网络服务或仪器配套软件的场景。",
  "description_en": "This is a non-physical software communication component that implements SUN RPC client/server communication over UDP, uses the port mapper to discover service ports, and performs XDR packing, unpacking, and remote procedure calls. It is used in lab systems that need to access RPC-based network services or instrument-associated software.",
  "tag_hints": [
    "Sun RPC",
    "UDP communication",
    "port mapper",
    "XDR serialization",
    "RPC client",
    "RPC server",
    "network protocol helper"
  ],
  "actions": [
    {
      "action_name": "auto-pack_auth",
      "description": "打包 RPC 认证信息。",
      "description_en": "Pack RPC authentication data."
    },
    {
      "action_name": "auto-pack_auth_unix",
      "description": "打包 UNIX 风格的 RPC 认证信息。",
      "description_en": "Pack UNIX-style RPC authentication data."
    },
    {
      "action_name": "auto-pack_callheader",
      "description": "打包 RPC 调用头。",
      "description_en": "Pack an RPC call header."
    },
    {
      "action_name": "auto-pack_replyheader",
      "description": "打包 RPC 应答头。",
      "description_en": "Pack an RPC reply header."
    },
    {
      "action_name": "auto-unpack_auth",
      "description": "解包 RPC 认证信息。",
      "description_en": "Unpack RPC authentication data."
    },
    {
      "action_name": "auto-unpack_callheader",
      "description": "解包 RPC 调用头。",
      "description_en": "Unpack an RPC call header."
    },
    {
      "action_name": "auto-unpack_replyheader",
      "description": "解包 RPC 应答头。",
      "description_en": "Unpack an RPC reply header."
    },
    {
      "action_name": "auto-make_call",
      "description": "发起并完成一次 RPC 调用。",
      "description_en": "Make and complete an RPC call."
    },
    {
      "action_name": "auto-start_call",
      "description": "开始构建一次 RPC 调用。",
      "description_en": "Start building an RPC call."
    },
    {
      "action_name": "auto-do_call",
      "description": "执行一次 RPC 网络调用。",
      "description_en": "Execute an RPC network call."
    },
    {
      "action_name": "auto-mkcred",
      "description": "创建 RPC 凭据。",
      "description_en": "Create RPC credentials."
    },
    {
      "action_name": "auto-mkverf",
      "description": "创建 RPC 校验字段。",
      "description_en": "Create an RPC verifier."
    },
    {
      "action_name": "auto-call_0",
      "description": "调用过程 0，通常用于基础连通性或空操作请求。",
      "description_en": "Call procedure 0, typically used for basic connectivity or a null operation."
    },
    {
      "action_name": "auto-set_reply_handler",
      "description": "设置 RPC 应答处理函数。",
      "description_en": "Set the RPC reply handler."
    },
    {
      "action_name": "auto-set_timeout",
      "description": "设置 RPC 调用超时时间。",
      "description_en": "Set the RPC call timeout."
    },
    {
      "action_name": "auto-pack_mapping",
      "description": "打包端口映射条目。",
      "description_en": "Pack a port-mapping entry."
    },
    {
      "action_name": "auto-pack_pmaplist",
      "description": "打包端口映射列表。",
      "description_en": "Pack a port-mapper list."
    },
    {
      "action_name": "auto-pack_call_args",
      "description": "打包远程调用参数。",
      "description_en": "Pack remote call arguments."
    },
    {
      "action_name": "auto-unpack_mapping",
      "description": "解包端口映射条目。",
      "description_en": "Unpack a port-mapping entry."
    },
    {
      "action_name": "auto-unpack_pmaplist",
      "description": "解包端口映射列表。",
      "description_en": "Unpack a port-mapper list."
    },
    {
      "action_name": "auto-unpack_call_result",
      "description": "解包远程调用结果。",
      "description_en": "Unpack a remote call result."
    },
    {
      "action_name": "auto-set",
      "description": "向端口映射器注册服务映射。",
      "description_en": "Register a service mapping with the port mapper."
    },
    {
      "action_name": "auto-unset",
      "description": "从端口映射器注销服务映射。",
      "description_en": "Unregister a service mapping from the port mapper."
    },
    {
      "action_name": "auto-get_port",
      "description": "查询 RPC 服务对应的端口。",
      "description_en": "Get the port associated with an RPC service."
    },
    {
      "action_name": "auto-dump",
      "description": "获取端口映射器中的映射列表。",
      "description_en": "Dump the mapping list from the port mapper."
    },
    {
      "action_name": "auto-callit",
      "description": "通过端口映射器发起间接远程调用。",
      "description_en": "Perform an indirect remote call through the port mapper."
    },
    {
      "action_name": "auto-my_reply_handler",
      "description": "处理收到的 RPC 应答。",
      "description_en": "Handle a received RPC reply."
    },
    {
      "action_name": "auto-register",
      "description": "注册 RPC 服务或处理器。",
      "description_en": "Register an RPC service or handler."
    },
    {
      "action_name": "auto-unregister",
      "description": "注销 RPC 服务或处理器。",
      "description_en": "Unregister an RPC service or handler."
    },
    {
      "action_name": "auto-handle",
      "description": "处理单个 RPC 请求。",
      "description_en": "Handle a single RPC request."
    },
    {
      "action_name": "auto-turn_around",
      "description": "将请求处理为对应的 RPC 应答。",
      "description_en": "Turn a request into the corresponding RPC reply."
    },
    {
      "action_name": "auto-handle_0",
      "description": "处理过程 0 请求。",
      "description_en": "Handle procedure 0 requests."
    },
    {
      "action_name": "auto-addpackers",
      "description": "添加自定义打包器和解包器。",
      "description_en": "Add custom packers and unpackers."
    },
    {
      "action_name": "auto-loop",
      "description": "进入 RPC 服务循环。",
      "description_en": "Enter the RPC service loop."
    },
    {
      "action_name": "auto-session",
      "description": "处理一次 RPC 会话。",
      "description_en": "Handle one RPC session."
    },
    {
      "action_name": "auto-forkingloop",
      "description": "以派生进程方式运行 RPC 服务循环。",
      "description_en": "Run the RPC service loop using forked processes."
    },
    {
      "action_name": "auto-forksession",
      "description": "以派生进程方式处理一次 RPC 会话。",
      "description_en": "Handle one RPC session using a forked process."
    }
  ]
}

